parameters.functionCode:
const bruteForce = $node['Check Brute Force'].json;
const suspicious = $node['Check Suspicious Logins'].json;

const bfList = Array.isArray(bruteForce) ? bruteForce : (bruteForce?.email ? [bruteForce] : []);
const susList = Array.isArray(suspicious) ? suspicious : (suspicious?.email ? [suspicious] : []);

const alerts = [];

for (const bf of bfList) {
  if (bf.email) alerts.push({ type: 'brute_force', severity: 'high', email: bf.email, ip: bf.ip_address, attempts: bf.attempts, message: `${bf.attempts} failed login attempts from ${bf.ip_address}` });
}

for (const sus of susList) {
  if (sus.email) alerts.push({ type: 'suspicious_login', severity: 'medium', email: sus.email, ips: sus.ips, message: `Login from ${sus.login_count} different IPs in 1 hour` });
}

return [{ json: { has_alerts: alerts.length > 0, alerts, checked_at: new Date().toISOString() } }];

